class Server:
    def __init__(self, id, priority, capacity, period):
        self.id = id
        self.priority = priority
        self.C = capacity
        self.T = period

class LocalResource:
    def __init__(self, id, tasks_accessing):
        self.id = id
        self.ceiling_priority = max(t.priority for t in tasks_accessing)

def acquire_local_resource(task_i, resource):
    task_i.current_priority = max(task_i.priority, resource.ceiling_priority)
    # If server capacity exhausted, suspend task/server

class GlobalResource:
    def __init__(self, id, servers_accessing):
        self.id = id
        self.ceiling_priority = max(s.priority for s in servers_accessing)

def acquire_global_resource(task_i, server_S, resource, overrun_payback_enabled):
    task_i.current_priority = max(task_i.priority, resource.ceiling_priority)
    if server_S.capacity_exhausted and task_i.holds_global_resource:
        server_S.allow_overrun = True
        # Execute until resource released
        if overrun_payback_enabled:
            server_S.next_period_capacity -= overrun_amount

def calculate_server_overrun_time(server_S, tasks_in_S, global_resources):
    max_overrun = 0
    for task_i in tasks_in_S:
        for resource_r in global_resources:
            if task_i.accesses(resource_r):
                max_overrun = max(max_overrun, task_i.b_r)
    return max_overrun

def calculate_server_blocking(server_S, all_servers, global_resources):
    max_blocking = 0
    for lower_priority_server_X in all_servers:
        if lower_priority_server_X.priority < server_S.priority:
            for task_in_X in lower_priority_server_X.tasks:
                for resource_r in global_resources:
                    if task_in_X.accesses(resource_r) and resource_r.ceiling_priority >= server_S.priority:
                        max_blocking = max(max_blocking, task_in_X.b_r)
    return max_blocking

def calculate_task_blocking(task_i, tasks_in_same_app, local_resources, global_resources):
    max_blocking = 0
    for lower_priority_task_j in tasks_in_same_app:
        if lower_priority_task_j.priority < task_i.priority:
            for resource_r in lower_priority_task_j.accessed_resources:
                if resource_r.type == 'local' and resource_r.ceiling_priority >= task_i.priority:
                    max_blocking = max(max_blocking, lower_priority_task_j.b_r)
                elif resource_r.type == 'global' and resource_r.ceiling_priority >= task_i.priority:
                    max_blocking = max(max_blocking, lower_priority_task_j.b_r)
    return max_blocking

def get_higher_priority_tasks(task_i, all_tasks_in_app):
    return [t for t in all_tasks_in_app if t.priority < task_i.priority]

def get_higher_priority_servers(server_S, all_servers):
    return [s for s in all_servers if s.priority < server_S.priority]

def calculate_server_induced_jitter(server_S, SO_S, payback_enabled):
    if payback_enabled:
        return server_S.T - server_S.C - SO_S
    else:
        return server_S.T - server_S.C

def calculate_server_response_time_hsrp_payback(server_S, hp_servers, B_S):
    w_S_n = B_S + server_S.C
    while True:
        hp_server_interference = 0
        for hp_server_X in hp_servers:
            XO_X, C_X_prime = get_hp_server_execution_times(hp_server_X, True) # From Def 14
            num_invocations = ceil(w_S_n / hp_server_X.T)
            hp_server_interference += XO_X # First invocation
            hp_server_interference += max(0, num_invocations - 1) * C_X_prime # Subsequent invocations

        w_S_n_plus_1 = B_S + server_S.C + hp_server_interference

        if w_S_n_plus_1 == w_S_n:
            R_S = w_S_n
            break
        if w_S_n_plus_1 > server_S.T:
            return float('inf')
        w_S_n = w_S_n_plus_1
    return R_S

def calculate_server_response_time_hsrp_no_payback_normal_capacity(server_S, hp_servers, B_S):
    w_S_n = B_S + server_S.C
    while True:
        hp_server_interference = 0
        for hp_server_X in hp_servers:
            XO_X, _ = get_hp_server_execution_times(hp_server_X, False) # From Def 14
            num_invocations = ceil(w_S_n / hp_server_X.T)
            hp_server_interference += num_invocations * XO_X

        w_S_n_plus_1 = B_S + server_S.C + hp_server_interference

        if w_S_n_plus_1 == w_S_n:
            R_S = w_S_n
            break
        if w_S_n_plus_1 > server_S.T:
            return float('inf')
        w_S_n = w_S_n_plus_1
    return R_S

def calculate_server_response_time_hsrp_no_payback_with_own_overrun(server_S, hp_servers, B_S, SO_S):
    w_S_n = B_S + server_S.C + SO_S
    while True:
        hp_server_interference = 0
        for hp_server_X in hp_servers:
            XO_X, _ = get_hp_server_execution_times(hp_server_X, False) # From Def 14
            num_invocations = ceil(w_S_n / hp_server_X.T)
            hp_server_interference += num_invocations * XO_X

        w_S_n_plus_1 = B_S + server_S.C + SO_S + hp_server_interference

        if w_S_n_plus_1 == w_S_n:
            R_S = w_S_n
            break
        if w_S_n_plus_1 > server_S.T:
            return float('inf')
        w_S_n = w_S_n_plus_1
    return R_S
